"""Personal-folder analyzer (Documents, Pictures, Videos, Desktop, any folder).

Reports what takes space and what looks unnecessary, with a reason for each
finding. It never moves or deletes anything by itself.
"""

import heapq
import os
import time

from .fsutil import dir_size, is_link_entry
from .organizer import category_of
from .scanner import ext_of

DAY = 86400

# Folders that are regenerated by tools; reported as a whole instead of walked.
DEV_DIRS = {
    "node_modules": "node_modules",
    "__pycache__": "pycache",
    ".pytest_cache": "pycache",
    ".mypy_cache": "pycache",
    ".ruff_cache": "pycache",
    ".tox": "venv",
    ".next": "build_cache",
    ".parcel-cache": "build_cache",
    ".gradle": "build_cache",
}
JUNK_EXT = {"tmp": "temp_file", "dmp": "dump", "crdownload": "partial", "part": "partial"}
BACKUP_EXT = {"bak", "old", "bck"}
INSTALLER_EXT = {"exe", "msi", "iso", "img"}


def _dev_kind(entry):
    name = entry.name
    if name in DEV_DIRS:
        return DEV_DIRS[name]
    if name in ("venv", ".venv", "env") and os.path.isfile(os.path.join(entry.path, "pyvenv.cfg")):
        return "venv"
    if name == "target" and os.path.isfile(os.path.join(os.path.dirname(entry.path), "Cargo.toml")):
        return "build_cache"
    return None


def analyze(job, folder, top_n=150):
    now = time.time()
    folder = os.path.abspath(folder)
    cats = {}
    largest, old_big = [], []
    findings = []
    subfolders = {}
    total = files = 0
    stack = [(folder, None)]
    job.update(message="analyzing", current=folder)

    while stack:
        current, top = stack.pop()
        try:
            it = os.scandir(current)
        except OSError:
            continue
        with it:
            for e in it:
                try:
                    if e.is_dir(follow_symlinks=False):
                        if is_link_entry(e):
                            continue
                        top_name = top or e.name
                        kind = _dev_kind(e)
                        if kind:
                            size, count = dir_size(e.path, job=job)
                            total += size
                            files += count
                            subfolders[top_name] = subfolders.get(top_name, 0) + size
                            cats.setdefault("dev", [0, 0])
                            cats["dev"][0] += size
                            cats["dev"][1] += count
                            if size:
                                findings.append({"path": e.path, "size": size, "reason": kind, "dir": True, "files": count})
                            continue
                        stack.append((e.path, top_name))
                        continue
                    st = e.stat(follow_symlinks=False)
                except OSError:
                    continue
                size, mtime = st.st_size, st.st_mtime
                total += size
                files += 1
                if top:
                    subfolders[top] = subfolders.get(top, 0) + size
                cat = category_of(e.name)
                c = cats.setdefault(cat, [0, 0])
                c[0] += size
                c[1] += 1
                item = (size, e.path, mtime)
                if len(largest) < top_n:
                    heapq.heappush(largest, item)
                elif size > largest[0][0]:
                    heapq.heapreplace(largest, item)
                age = (now - mtime) / DAY
                if age > 730 and size >= 10 * 1024 * 1024:
                    if len(old_big) < top_n:
                        heapq.heappush(old_big, item)
                    elif size > old_big[0][0]:
                        heapq.heapreplace(old_big, item)
                ext = ext_of(e.name)
                reason = None
                if ext in JUNK_EXT:
                    reason = JUNK_EXT[ext]
                elif e.name.startswith("~$") and size < 1024 * 1024:
                    reason = "office_lock"
                elif e.name.lower() in ("thumbs.db", ".ds_store"):
                    reason = "os_junk"
                elif ext == "log" and size >= 10 * 1024 * 1024:
                    reason = "big_log"
                elif ext in BACKUP_EXT and size >= 1024 * 1024:
                    reason = "backup"
                elif ext in INSTALLER_EXT and size >= 50 * 1024 * 1024:
                    reason = "installer"
                if reason:
                    findings.append({"path": e.path, "size": size, "reason": reason, "dir": False, "mtime": mtime})
                if files % 2000 == 0:
                    job.check()
                    job.update(current=current, count=files)

    # Same backup kept twice (".bak" next to a ".zip" of it) is common; flag the pair.
    paths = {os.path.normcase(f["path"]) for f in findings if f["reason"] == "backup"}
    for f in findings:
        if f["reason"] == "backup":
            stem = os.path.splitext(f["path"])[0]
            for alt in (stem + ".zip", stem + ".7z", os.path.dirname(f["path"]) + ".zip"):
                if os.path.normcase(alt) not in paths and os.path.isfile(alt):
                    f["reason"] = "backup_zipped"
                    f["keep"] = os.path.basename(alt)
                    break

    findings.sort(key=lambda f: f["size"], reverse=True)
    try:
        from . import history
        history.save_snapshot("folder", folder, dict(subfolders), total)
    except OSError:
        pass
    to_list = lambda heap: [{"path": p, "size": s, "mtime": m} for s, p, m in sorted(heap, reverse=True)]
    return {
        "folder": folder,
        "total": total,
        "files": files,
        "categories": sorted(({"cat": k, "size": v[0], "files": v[1]} for k, v in cats.items()), key=lambda x: -x["size"]),
        "subfolders": sorted(({"name": k, "path": os.path.join(folder, k), "size": v} for k, v in subfolders.items()),
                             key=lambda x: -x["size"])[:60],
        "largest": to_list(largest),
        "old_big": to_list(old_big),
        "findings": findings[:1000],
        "findings_size": sum(f["size"] for f in findings),
    }
